import json
d=json.load(open('$f'))
for k,v in d.items():
    if isinstance(v, dict) and 'acc' in v:
        print(f'  {k}: acc={v[\"acc\"]:.4f}')
    elif isinstance(v, dict):
        for sk,sv in v.items():
            if isinstance(sv, dict) and 'acc' in sv:
                print(f'  {k}/{sk}: acc={sv[\"acc\"]:.4f}')
" 2>/dev/null; done

